//! Balance transfer analysis — and the sentence the marketing never contains:
//!
//! **A balance transfer does not reduce debt.** It moves it, and it charges you for the move.
//!
//! The instant it completes you owe MORE than you did — the balance plus the fee — and net worth has
//! gone down by exactly the fee. Everything good about it is a bet that the interest avoided over the
//! promotional window will exceed that fee, and that bet is only won by paying the balance down
//! during the window. This module prices the bet honestly, including the ways it is lost:
//!
//! - **The fee is added to the balance.** Transfer $5,000 at 3% and you owe $5,150 on day one.
//! - **The go-to rate can be worse.** Escaping 24.99% into a 0% promo that reverts to 29.99% is a
//!   loss unless the balance is gone by then, and "unless" is doing a great deal of work.
//! - **The saving is against what you would actually pay**, not against the balance sitting still.
//!   If you would have cleared it in five months anyway, a twelve-month promotion saves almost
//!   nothing and the fee is simply a cost.
//! - **The limit caps it**, and filling a new card to its limit has a price of its own that is not
//!   interest.
use crate::money::{money, scale, Money, Rounding};
use crate::position::AccountPosition;

#[derive(Debug, Clone, PartialEq)]
pub struct TransferOffer {
    pub id: String,
    pub institution: String,
    /// Usually 0. A fraction: 0.0499 for 4.99%.
    pub promo_apr: f64,
    pub promo_months: i64,
    /// A fraction of the transferred amount: 0.03 for 3%.
    pub transfer_fee_rate: f64,
    /// Some offers charge a floor regardless of size.
    pub transfer_fee_min: Option<Money>,
    /// The rate the REMAINING balance reverts to. The number the offer prints smallest.
    pub go_to_apr: f64,
    /// Caps what can move. ABSENT means unknown, not unlimited.
    pub credit_limit: Option<Money>,
    pub offer_expires: Option<String>,
}

#[derive(Debug, Clone, PartialEq)]
pub struct TransferAssessment {
    pub offer_id: String,
    pub institution: String,
    pub source_account: String,
    /// What actually moves, after the limit caps it.
    pub moved: Money,
    /// POSITIVE. Added to the transferred balance, not taken off it.
    pub fee: Money,
    /// What you owe on the new card the moment it lands: moved + fee.
    pub opening_balance: Money,
    /// Interest you would have paid on the source over the promo window, at the same payment.
    pub interest_without: Money,
    /// Interest you pay having transferred, over the same window.
    pub interest_with: Money,
    /// `interest_without − interest_with`. BEFORE the fee.
    pub interest_avoided: Money,
    /// `interest_avoided − fee`. NEGATIVE when the move costs more than it saves.
    pub net_benefit: Money,
    pub worth_it: bool,
    /// What is still owed when the promotional rate ends. Zero is the only comfortable answer.
    pub balance_at_promo_end: Money,
    /// A year of the go-to rate on whatever is left. The cost of not finishing.
    pub cost_of_not_finishing: Money,
    /// The monthly payment that clears the whole thing inside the window.
    pub required_monthly: Money,
    pub warnings: Vec<String>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Accrual {
    pub interest: i64,
    pub balance: i64,
}

/// Simple monthly accrual: interest on the balance, then the payment.
///
/// Deliberately the SAME model `payoff` uses, so a transfer assessment and a payoff schedule cannot
/// disagree about the same debt.
pub fn accrue(balance_minor: i64, apr: f64, payment_minor: i64, months: i64) -> Accrual {
    let mut b = balance_minor;
    let mut interest = 0i64;
    let mut i = 0;
    while i < months && b > 0 {
        let charge = (b as f64 * (apr / 12.0)).round() as i64;
        interest += charge;
        b = (b + charge - payment_minor).max(0);
        i += 1;
    }
    Accrual { interest, balance: b }
}

pub struct TransferOptions {
    /// What you will actually put against this debt each month — the SAME on both sides of the
    /// comparison, because otherwise the answer measures a change of behaviour, not the offer.
    pub monthly_payment: Money,
    /// How much to move. NONE means the whole source balance, capped by the offer's limit.
    pub amount: Option<Money>,
    /// Utilisation above which filling the new line is called out.
    pub utilisation_concern: f64,
}

impl TransferOptions {
    pub fn new(monthly_payment: Money) -> Self {
        TransferOptions { monthly_payment, amount: None, utilisation_concern: 0.7 }
    }
}

fn pct(rate: f64) -> f64 {
    (rate * 10_000.0).round() / 100.0
}

pub fn assess_transfer(source: &AccountPosition, offer: &TransferOffer, opts: &TransferOptions) -> TransferAssessment {
    let currency = source.balance.currency;
    let mut warnings: Vec<String> = Vec::new();

    let owed = source.owed.map(|o| o.minor).unwrap_or(0);
    let wanted = opts.amount.map(|a| a.minor).unwrap_or(owed);
    let mut moved = wanted.min(owed).max(0);

    match offer.credit_limit {
        Some(limit) if moved > limit.minor => {
            warnings.push(format!(
                "only {} of {} minor units fits inside {}'s limit — the rest stays where it is, at its own rate, and the plan has to cover both",
                limit.minor, moved, offer.institution
            ));
            moved = limit.minor;
        }
        Some(_) => {}
        None => warnings.push(format!("{}'s limit is unknown, so the whole balance is assumed to fit — an assumption, not a fact", offer.institution)),
    }

    let fee_minor = ((moved as f64 * offer.transfer_fee_rate).round() as i64).max(offer.transfer_fee_min.map(|m| m.minor).unwrap_or(0));
    // THE FEE IS ADDED. You transfer $5,000 at 3% and owe $5,150 the moment it lands.
    let opening = moved + fee_minor;

    let without = accrue(owed, source.apr.unwrap_or(0.0), opts.monthly_payment.minor, offer.promo_months);
    let with_t = accrue(opening, offer.promo_apr, opts.monthly_payment.minor, offer.promo_months);
    let avoided = without.interest - with_t.interest;
    let net = avoided - fee_minor;

    if source.apr.is_none() {
        warnings.push(format!(
            "{}'s rate is unknown, so the interest avoided is computed at 0% — the saving below is a FLOOR and the real one is larger",
            source.institution
        ));
    }
    if offer.go_to_apr > source.apr.unwrap_or(0.0) {
        warnings.push(format!(
            "the go-to rate of {}% is HIGHER than the {}% you are leaving — anything still owed when the promotion ends costs more than it does today",
            pct(offer.go_to_apr),
            pct(source.apr.unwrap_or(0.0))
        ));
    }
    if with_t.balance > 0 {
        warnings.push(format!(
            "at {} a month, {} minor units are still owed when the promotion ends — the whole balance begins accruing at {}% at once, not gradually",
            opts.monthly_payment.minor,
            with_t.balance,
            pct(offer.go_to_apr)
        ));
    }
    if opts.monthly_payment.minor <= (opening as f64 * (offer.promo_apr / 12.0)).round() as i64 {
        warnings.push("the payment does not cover even the promotional interest, so the balance grows — this is not a plan, it is a delay".to_string());
    }
    if let Some(limit) = offer.credit_limit {
        if limit.minor > 0 {
            let utilisation = opening as f64 / limit.minor as f64;
            if utilisation >= opts.utilisation_concern {
                warnings.push(format!(
                    "this fills {}% of the new line — a near-full card costs you on a credit score, which is a real price that is not interest",
                    (utilisation * 100.0).round()
                ));
            }
        }
    }
    if net <= 0 {
        warnings.push(format!(
            "the fee of {fee_minor} is not covered by the {avoided} of interest it avoids over {} month(s) — on these numbers the move loses money",
            offer.promo_months
        ));
    }

    TransferAssessment {
        offer_id: offer.id.clone(),
        institution: offer.institution.clone(),
        source_account: source.account.clone(),
        moved: money(moved, currency),
        fee: money(fee_minor, currency),
        opening_balance: money(opening, currency),
        interest_without: money(without.interest, currency),
        interest_with: money(with_t.interest, currency),
        interest_avoided: money(avoided, currency),
        net_benefit: money(net, currency),
        worth_it: net > 0,
        balance_at_promo_end: money(with_t.balance, currency),
        cost_of_not_finishing: money((with_t.balance as f64 * offer.go_to_apr).round() as i64, currency),
        // CEIL, because a payment that is a cent short leaves a balance to revert.
        required_monthly: money(
            if offer.promo_months > 0 { (opening as f64 / offer.promo_months as f64).ceil() as i64 } else { opening },
            currency,
        ),
        warnings,
    }
}

/// THE FACT THE MARKETING OMITS: net worth falls by exactly the fee, on day one.
///
/// It is not a saving, it is a PURCHASE — you are buying a lower rate for a window, and the price is
/// charged whether or not you use the window well.
pub fn debt_after_transfer(source: &AccountPosition, a: &TransferAssessment) -> Money {
    money(source.owed.map(|o| o.minor).unwrap_or(0) + a.fee.minor, source.balance.currency)
}

/// Every offer against every debt, best net benefit first.
///
/// Losers are KEPT, so a bad offer is visibly bad rather than absent — an offer that vanished would
/// simply be re-found and re-assessed next month.
pub fn rank_transfers(debts: &[AccountPosition], offers: &[TransferOffer], opts: &TransferOptions) -> Vec<TransferAssessment> {
    let mut out: Vec<TransferAssessment> = Vec::new();
    for d in debts {
        if d.owed.is_none() {
            continue;
        }
        for o in offers {
            // Moving a balance onto the card it is already on is not a transfer.
            if o.institution == d.institution {
                continue;
            }
            out.push(assess_transfer(d, o, opts));
        }
    }
    out.sort_by_key(|a| std::cmp::Reverse(a.net_benefit.minor));
    out
}

/// A year of the go-to rate on the whole opening balance — what the offer costs if nothing is paid.
pub fn worst_case_annual(a: &TransferAssessment, offer: &TransferOffer) -> Money {
    scale(a.opening_balance, offer.go_to_apr, Rounding::HalfUp)
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::account::Kind;
    use crate::money::usd;

    // SYNTHETIC FIXTURES ONLY.
    fn src(account: &str, institution: &str, owed: i64, apr: Option<f64>) -> AccountPosition {
        AccountPosition {
            account: account.to_string(),
            institution: institution.to_string(),
            kind: Kind::Credit,
            balance: usd(-owed),
            as_of: "2026-06-30".to_string(),
            rolled_forward: 0,
            is_debt: true,
            owed: Some(usd(owed)),
            credit_limit: None,
            available: None,
            utilisation: None,
            apr,
            daily_interest: None,
            minimum_payment: None,
        }
    }

    #[allow(clippy::too_many_arguments)]
    fn offer(id: &str, institution: &str, promo_apr: f64, promo_months: i64, fee_rate: f64, go_to: f64, limit: Option<i64>, fee_min: Option<i64>) -> TransferOffer {
        TransferOffer {
            id: id.to_string(),
            institution: institution.to_string(),
            promo_apr,
            promo_months,
            transfer_fee_rate: fee_rate,
            transfer_fee_min: fee_min.map(usd),
            go_to_apr: go_to,
            credit_limit: limit.map(usd),
            offer_expires: None,
        }
    }

    #[test]
    fn the_fee_is_added_to_the_balance_so_you_owe_more_on_day_one() {
        let s = src("visa", "chase", 500_000, Some(0.2499));
        let o = offer("o1", "newbank", 0.0, 12, 0.03, 0.2999, Some(600_000), None);
        let a = assess_transfer(&s, &o, &TransferOptions::new(usd(50_000)));
        assert_eq!(a.moved.minor, 500_000);
        assert_eq!(a.fee.minor, 15_000);
        // $5,000 transferred at 3% and you owe $5,150 the moment it lands. NOT $5,000.
        assert_eq!(a.opening_balance.minor, 515_000);
        // And net worth is down by exactly the fee — a purchase, not a saving.
        assert_eq!(debt_after_transfer(&s, &a).minor, 515_000);
    }

    #[test]
    fn the_saving_is_measured_against_what_you_would_actually_pay() {
        // Measured by running finance-transfer.ts on this exact fixture.
        let a = assess_transfer(&src("visa", "chase", 500_000, Some(0.2499)), &offer("o1", "newbank", 0.0, 12, 0.03, 0.2999, Some(600_000), None), &TransferOptions::new(usd(50_000)));
        assert_eq!(a.interest_without.minor, 66_578, "at 50000 a month, NOT the balance sitting still");
        assert_eq!(a.interest_with.minor, 0);
        assert_eq!(a.interest_avoided.minor, 66_578);
        assert_eq!(a.net_benefit.minor, 51_578, "avoided MINUS the fee");
        assert!(a.worth_it);
        assert_eq!(a.balance_at_promo_end.minor, 0, "the only comfortable answer");
        assert_eq!(a.required_monthly.minor, 42_917, "515000/12 rounded UP — a cent short leaves a balance to revert");
    }

    #[test]
    fn a_promotion_too_short_to_finish_in_leaves_a_balance_that_reverts_all_at_once() {
        let o = offer("o7", "newbank", 0.0, 3, 0.03, 0.2999, Some(600_000), None);
        let a = assess_transfer(&src("visa", "chase", 500_000, Some(0.2499)), &o, &TransferOptions::new(usd(50_000)));
        assert_eq!(a.balance_at_promo_end.minor, 365_000);
        assert_eq!(a.cost_of_not_finishing.minor, 109_464, "a year of the go-to rate on what is left");
        assert!(a.warnings.iter().any(|w| w.contains("begins accruing at 29.99% at once, not gradually")));
        // It still shows a positive net over the window — which is exactly why the balance left
        // over has to be reported beside it rather than folded in.
        assert_eq!(a.net_benefit.minor, 13_748);
        assert!(a.worth_it, "over the WINDOW; the cost of not finishing is the other half of the picture");
    }

    #[test]
    fn a_payment_that_does_not_cover_the_promotional_interest_is_named_a_delay() {
        let o = offer("o5", "newbank", 0.0499, 12, 0.03, 0.2999, Some(600_000), None);
        let a = assess_transfer(&src("visa", "chase", 500_000, Some(0.2499)), &o, &TransferOptions::new(usd(1_000)));
        assert_eq!(a.balance_at_promo_end.minor, 529_016, "it GREW");
        assert!(a.warnings.iter().any(|w| w.contains("this is not a plan, it is a delay")));
    }

    #[test]
    fn a_limit_caps_the_move_and_the_remainder_is_named() {
        let o = offer("o2", "newbank", 0.0, 12, 0.03, 0.2999, Some(300_000), None);
        let a = assess_transfer(&src("visa", "chase", 500_000, Some(0.2499)), &o, &TransferOptions::new(usd(50_000)));
        assert_eq!(a.moved.minor, 300_000);
        assert!(a.warnings[0].contains("the rest stays where it is, at its own rate, and the plan has to cover both"));
        // The fee pushes the opening balance PAST the limit — 103% of the new line.
        assert_eq!(a.opening_balance.minor, 309_000);
        assert!(a.warnings.iter().any(|w| w.contains("fills 103% of the new line")));
    }

    #[test]
    fn an_unknown_limit_is_an_assumption_and_says_so() {
        let a = assess_transfer(&src("visa", "chase", 500_000, Some(0.2499)), &offer("o3", "newbank", 0.0, 12, 0.03, 0.2999, None, None), &TransferOptions::new(usd(50_000)));
        assert!(a.warnings[0].contains("assumed to fit — an assumption, not a fact"));
        // ABSENT means unknown, not unlimited — so no utilisation warning is invented either.
        assert!(!a.warnings.iter().any(|w| w.contains("of the new line")));
    }

    #[test]
    fn an_unknown_source_rate_makes_the_saving_a_floor_rather_than_a_guess() {
        let a = assess_transfer(&src("visa", "chase", 500_000, None), &offer("o4", "newbank", 0.0, 12, 0.03, 0.2999, Some(600_000), None), &TransferOptions::new(usd(50_000)));
        // Computed at 0%, so the move reads as a pure loss of the fee — the conservative direction.
        assert_eq!(a.interest_avoided.minor, 0);
        assert_eq!(a.net_benefit.minor, -15_000);
        assert!(!a.worth_it);
        assert!(a.warnings[0].contains("the saving below is a FLOOR and the real one is larger"));
    }

    #[test]
    fn a_minimum_fee_can_make_a_small_transfer_lose_money() {
        let o = offer("o6", "newbank", 0.0, 12, 0.03, 0.2999, Some(600_000), Some(1_000));
        let a = assess_transfer(&src("visa", "chase", 10_000, Some(0.2499)), &o, &TransferOptions::new(usd(5_000)));
        // 3% of 10000 is 300, but the floor is 1000 — and it avoids only 323.
        assert_eq!(a.fee.minor, 1_000);
        assert_eq!(a.interest_avoided.minor, 323);
        assert_eq!(a.net_benefit.minor, -677);
        assert!(!a.worth_it);
        assert!(a.warnings.iter().any(|w| w.contains("on these numbers the move loses money")));
    }

    #[test]
    fn a_transfer_onto_the_same_institution_is_not_a_transfer() {
        let debts = vec![src("visa", "chase", 500_000, Some(0.2499)), src("store", "storeco", 80_000, Some(0.0999))];
        let offers = vec![offer("o1", "newbank", 0.0, 12, 0.03, 0.2999, Some(600_000), None), offer("o2", "chase", 0.0, 12, 0.03, 0.2999, Some(600_000), None)];
        let r = rank_transfers(&debts, &offers, &TransferOptions::new(usd(50_000)));
        let got: Vec<(&str, &str, i64)> = r.iter().map(|a| (a.offer_id.as_str(), a.source_account.as_str(), a.net_benefit.minor)).collect();
        // chase→chase is absent. Best net benefit first, and the LOSERS ARE KEPT so a bad offer is
        // visibly bad rather than quietly missing.
        assert_eq!(got, vec![("o1", "visa", 51_578), ("o1", "store", -1_479), ("o2", "store", -1_479)]);
    }

    #[test]
    fn the_accrual_is_the_same_model_the_payoff_schedule_uses() {
        assert_eq!(accrue(500_000, 0.2499, 20_000, 12), Accrual { interest: 110_814, balance: 370_814 });
        assert_eq!(accrue(515_000, 0.0, 20_000, 12), Accrual { interest: 0, balance: 275_000 });
        // No payment at all: the balance compounds rather than standing still.
        assert_eq!(accrue(100_000, 0.2, 0, 3), Accrual { interest: 5_084, balance: 105_084 });
        // A cleared balance stops accruing rather than going negative.
        assert_eq!(accrue(1_000, 0.2, 50_000, 12), Accrual { interest: 17, balance: 0 });
        assert_eq!(accrue(0, 0.2, 100, 12), Accrual { interest: 0, balance: 0 });
    }

    #[test]
    fn the_worst_case_is_a_year_of_the_go_to_rate_on_the_whole_opening_balance() {
        let o = offer("o1", "newbank", 0.0, 12, 0.03, 0.2999, Some(600_000), None);
        let a = assess_transfer(&src("visa", "chase", 500_000, Some(0.2499)), &o, &TransferOptions::new(usd(50_000)));
        assert_eq!(worst_case_annual(&a, &o).minor, 154_449, "what the offer costs if nothing is paid");
    }
}
